private async analyzeStory(storyId: number): Promise<StoryAnalysis> {
  const wi = await this.client.getWorkItemWithRelations(storyId);
  const relations = wi.relations || [];
  // Two DIFFERENT link types off the same story:
  const childIds = this.client.extractRelationIds(relations, 'System.LinkTypes.Hierarchy-Forward');      // QA Task + Bugs are children
  const testCaseIds = this.client.extractRelationIds(relations, 'Microsoft.VSTS.Common.TestedBy-Forward'); // test cases are a separate link, not children

  let qaTask: StoryAnalysis['qaTask'] = null;
  const childBugs: StoryAnalysis['bugs'] = [];

  const children = await this.client.getWorkItemsBatch(childIds);
  for (const child of children) {
    const type = child.fields?.['System.WorkItemType'];
    const title = child.fields?.['System.Title'] || '';
    // Identify the QA Task by title-contains (lowercased); its System.State drives the whole verdict downstream.
    if (type === 'Task' && title.toLowerCase().includes('qa test execution')) {
      qaTask = { id: child.id, title, state: child.fields['System.State'],
                 assignedTo: this.client.extractDisplayName(child.fields['System.AssignedTo']) };
    }
    if (type === 'Bug') childBugs.push({ id: child.id, title, state: child.fields['System.State'], linkedTcIds: [] } as any);
  }
  // Second round-trip per bug: a bug's OWN relations (not the story's) tell us which test cases it maps to.
  for (const bug of childBugs) bug.linkedTcIds = await this.findBugTcLinks(bug.id);
  return { storyId, storyTitle: wi.fields?.['System.Title'], qaTask, testCaseIds, bugs: childBugs };
}

private async resolveOutcomes(analysis: StoryAnalysis) {
  const results: PendingResult[] = [];
  const comments: PendingComment[] = [];

  // Guard 1: no QA Task -> nothing to grade, skip silently.
  if (!analysis.qaTask) {
    return { results: [], comments: [], skipped: analysis.testCaseIds.length };
  }
  // Guard 2: QA Task not Closed (lowercased - ADO state casing varies) -> refuse to guess.
  // Queue a reminder and skip rather than mark anything Passed on an unfinished run.
  if (analysis.qaTask.state.toLowerCase() !== 'closed') {
    comments.push({ workItemId: analysis.qaTask.id,
      comment: 'QA Test Execution pending. Please complete and close this task so results can be recorded.' });
    return { results: [], comments, skipped: analysis.testCaseIds.length };
  }

  const failedTcIds = new Set<number>();
  for (const bug of analysis.bugs) {
    for (const tcId of bug.linkedTcIds) {
      // Only fail cases that belong to THIS story; a bug linked to a foreign test case is ignored.
      if (analysis.testCaseIds.includes(tcId)) {
        failedTcIds.add(tcId); // Set -> a case hit by multiple bugs is recorded once
        results.push({ testCaseId: tcId, outcome: 'Failed', comment: `Bug #${bug.id}: ${bug.title}` });
      }
    }
  }
  // Everything not explicitly failed passes - the two buckets never overlap.
  for (const tcId of analysis.testCaseIds) {
    if (!failedTcIds.has(tcId)) results.push({ testCaseId: tcId, outcome: 'Passed', comment: 'Auto-resolved: no linked bugs' });
  }
  return { results, comments, skipped: 0 };
}

private async findBugTcLinks(bugId: number): Promise<number[]> {
  const bug = await this.client.getWorkItemWithRelations(bugId);
  const relations = bug.relations || [];
  const tcIds: number[] = [];

  for (const rel of relations) {
    // Accept all three link types - teams link bugs to test cases inconsistently,
    // and being strict about direction would miss real associations.
    if (
      rel.rel === 'Microsoft.VSTS.Common.TestedBy-Forward' ||
      rel.rel === 'Microsoft.VSTS.Common.TestedBy-Reverse' ||
      rel.rel === 'System.LinkTypes.Related'
    ) {
      // ADO relations carry the target ID only inside rel.url (.../workItems/1234), not as a field.
      const match = rel.url?.match(/workItems\/(\d+)/i);
      // Returns EVERY linked ID; resolveOutcomes narrows these to real test cases via the story's testCaseIds.
      if (match) tcIds.push(parseInt(match[1], 10));
    }
  }
  return tcIds;
}

private async postResults(planId: number, suiteId: number, results: PendingResult[], runName: string, dryRun: boolean): Promise<number | null> {
  // Step 1: results attach to test POINTS, not test cases directly - build the TC id -> point id bridge.
  // A test point = a test case intersected with this suite/config.
  const testPoints = await this.client.getTestPoints(suiteId, planId);
  const tcToPoint = new Map<number, number>();
  for (const tp of testPoints) tcToPoint.set(tp.testCaseReference.id, tp.id);

  // Drop any result whose case has no point in THIS suite, so a stray id can't break the run.
  const validResults = results.filter(r => tcToPoint.has(r.testCaseId));
  const pointIds = validResults.map(r => tcToPoint.get(r.testCaseId)!);
  if (dryRun) return null; // preview still validated point coverage above, but writes nothing

  // Step 2: create the run over those point IDs.
  const run = await this.client.createTestRun(runName, pointIds);
  // Step 3: creating the run AUTO-generates one empty result per point; we need those result IDs to update them.
  const runResults = await this.client.getTestRunResults(run.id);
  // Step 4: re-match each auto-created result back to its pending outcome by testCase.id, then PATCH.
  const updates = runResults
    .map(rr => ({ rr, pending: validResults.find(r => r.testCaseId === rr.testCase?.id) }))
    .filter(x => x.pending)
    .map(x => ({ id: x.rr.id, outcome: x.pending!.outcome, comment: x.pending!.comment }));
  await this.client.updateTestRunResults(run.id, updates);
  // Step 5: complete the run - flips it from in-progress to finished/reportable; skip it and results read as still running.
  await this.client.completeTestRun(run.id);
  return run.id;
}

private async showStatus(planId: number, suiteId: number): Promise<void> {
  const points = await this.client.getTestPoints(suiteId, planId);
  const outcomes: Record<string, number> = {};

  for (const tp of points) {
    // lastResultOutcome = the point's MOST RECENT run result; ?. because a never-run point has no 'results' at all.
    // 'Unspecified' bucket = not-yet-executed points, which is itself useful signal.
    const outcome = (tp as any).results?.lastResultOutcome || 'Unspecified';
    outcomes[outcome] = (outcomes[outcome] || 0) + 1;
  }
  console.log('Summary:', outcomes);
}
